<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import * as api from '@/api/modules/moldSales'
import {useCollaborationWorkspace} from '@/stores/collaborationWorkspace'
import {useMoldSalesPreferences,type MoldSalesView} from '@/composables/useMoldSalesPreferences'
import MoldSalesMatrix from './MoldSalesMatrix.vue'
import MoldCostEditor from './MoldCostEditor.vue'
import MoldSalesHistoryReview from './MoldSalesHistoryReview.vue'
const props=withDefaults(defineProps<{mode?:'sales'|'production'}>(),{mode:'sales'})
const emit=defineEmits<{maintain:[itemId?:number]}>()
const production=computed(()=>props.mode==='production'),workspace=useCollaborationWorkspace()
const route=useRoute(),router=useRouter(),user=useUserStore()
const data=ref<api.SalesPage>(),matrix=ref<api.MoldSalesMatrixPage>(),keyword=ref(''),filter=ref('all'),brandId=ref<number>(),page=ref(1),size=ref(50),loading=ref(false),error=ref('')
const preferences=useMoldSalesPreferences(props.mode),presentation=computed(()=>production.value?'detail':preferences.view.value)
const metadata=ref<api.MoldSalesOptions>({products:[],brands:[]}),ready=ref(false),productSearch=ref(''),productsOpen=ref(false)
const options=computed(()=>metadata.value.products),brands=computed(()=>metadata.value.brands)
const defaultIds=computed(()=>production.value?options.value.map(p=>p.productLineId):(metadata.value.defaultProductLineIds??options.value.slice(0,4).map(p=>p.productLineId)))
const selectedIds=computed(()=>(preferences.savedProductLineIds.value??defaultIds.value).filter(id=>options.value.some(p=>p.productLineId===id)))
const selectedProducts=computed(()=>selectedIds.value.map(id=>options.value.find(p=>p.productLineId===id)!).filter(Boolean))
const filteredProducts=computed(()=>options.value.filter(p=>`${p.productName} ${p.productCode||''} ${p.styleCode||''}`.toLowerCase().includes(productSearch.value.trim().toLowerCase())))
const current=computed(()=>presentation.value==='matrix'?matrix.value:data.value)
const choiceOpen=ref(false),choiceRows=ref<{groupId?:number;applicationId?:number;itemId?:number;productName:string;modelNames:string[];phoneCodes:string[];salesQuantity?:number|null}[]>([])
function chooseProducts(ids:number[]){preferences.chooseProducts(ids)}
function toggleProduct(id:number,checked:boolean){chooseProducts(checked?[...selectedIds.value,id]:selectedIds.value.filter(value=>value!==id))}
function chooseView(value:MoldSalesView){preferences.chooseView(value)}
function brandNames(row:api.MoldSalesGroup){return row.brandNames?.join(' / ')||'未登记品牌'}
const job=ref<api.SyncJob>(),detail=ref<api.SalesDetail>(),detailOpen=ref(false),detailPage=ref(1),detailTab=ref('orders'),detailLoading=ref(false)
const historyOpen=ref(false),history=ref<Awaited<ReturnType<typeof api.getMoldSalesHistory>>>([]),unmatchedOpen=ref(false)
const costOpen=ref(false),costGroupId=ref<number>(),costWritable=ref(false)
const archiveOpen=ref(false),archiveSources=ref<api.SalesArchiveSource[]>([]),archiveHash=ref(''),archiveLoading=ref(false),archiveSaving=ref(false),archiveError=ref(''),archiveUnknown=ref(false)
const archiveSource=computed(()=>archiveSources.value.find(source=>source.sha256===archiveHash.value))
let epoch=0,detailEpoch=0,optionsEpoch=0,archiveEpoch=0,readyAuth='',readyOwner:number|undefined,timer:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setTimeout>|undefined,disposed=false
const status=computed(()=>current.value?.status),isRunning=computed(()=>job.value?.status==='running')
const qty=(n:number|null|undefined)=>n==null?'—':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:0}).format(n)
const money=(n:number|null|undefined)=>n==null?'—':new Intl.NumberFormat('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:4}).format(n)
const date=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false,timeZone:'Asia/Shanghai'}):'尚未更新'
const canMaintainCost=computed(()=>status.value?.canReadCost===true&&status.value.canWriteCost===true)
const costLabel=(cost:api.MoldCost)=>cost.source==='actual'?'实际成本':'预算参考'
const sourceBreakdown=(sources:api.SalesSourceBreakdown|undefined)=>sources?`eccount ${qty(sources.eccount)} · crm ${qty(sources.crm)}`:''
const sourceLabel=(order:api.SalesOrder)=>order.source==='eccount'?'数据来自 eccount':'数据来自 crm'
function orderQuantity(order:api.SalesOrder){return order.quantity==null?'数量未填写':`${new Intl.NumberFormat('zh-CN',{maximumFractionDigits:20}).format(order.quantity)}${order.unit?.trim()?' '+order.unit:' · 单位未填写'}`}
function breakEvenIssue(cost:api.MoldCost){
 if(cost.breakEvenUnits!=null)return ''
 const price=cost.basis?.referenceSellingPrice?.trim(),unitCost=cost.basis?.referenceUnitProductionCost?.trim()
 if(!price||!unitCost||!Number.isFinite(Number(price))||!Number.isFinite(Number(unitCost)))return '待补参考售价和单件生产成本，暂不计算回本销量'
 return Number(price)<=Number(unitCost)?'参考售价未覆盖单件生产成本，暂不计算回本销量':'回本依据待核对'
}
function componentDifference(row:api.MoldSalesGroup){const p=row.production;if(!p)return '';return [['PC',p.pcTotal],['TPU',p.tpuTotal]].filter(([,value])=>value!==p.finishedTotal).map(([label,value])=>`${label} ${qty(value as number|null)}`).join(' · ')}
const canMaintainRowCost=(row:api.MoldSalesGroup)=>canMaintainCost.value&&row.canWriteCost===true&&!row.costConflict
function editCost(row:api.MoldSalesGroup){if(!status.value?.canReadCost)return;costWritable.value=canMaintainRowCost(row);costGroupId.value=row.groupId;costOpen.value=true}
async function costSaved(){await load();if(detailOpen.value&&detail.value)await loadDetail()}
const eligibility:Record<string,string>={eligible:'计入销量',not_finished_stage:'半成品／非最终工序，不计入',not_finished_code:'商品编码待核对',cancelled:'已取消，不计入',deleted:'来源已删除，不计入',quantity_review:'数量待核对',missing_quantity:'数量未填写',identity_conflict:'商品身份待核对',unit_review:'单位待核对',company_review:'公司归属待核对',source_conflict:'来源资料待核对',status_review:'正式订单状态待核对',cancellation_review:'备注有取消疑义，待核对',header_record:'订单主表，明细另计',crm_period_reference:'同期 Excel 仅用于核对 CRM',missing_master:'缺少订单主表',outside_period:'不在本次来源日期范围'}
const orderStates:Record<string,string>={closed:'已完成',deal:'生产中',fully_shipped:'全部发货',partial_shipped:'部分发货',cancelled:'已取消',pending:'待审核',confirmed:'已确认',confirmed_deposit_push_production:'定金确认，已下推生产',sales_confirmed_pending_finance:'销售已确认，待财务',production_completed_pending_final_payment:'生产完成，待尾款',pending_shipment:'待发货',partial_arrived:'部分到货',fully_arrived:'全部到货'}
async function load(){
 if(!ready.value||readyAuth!==user.token||readyOwner!==user.profile?.userId)return
 const ticket=++epoch,auth=user.token;loading.value=true;error.value=''
 const params={page:page.value,size:size.value,keyword:keyword.value.trim(),filter:filter.value,brandId:brandId.value,productLineIds:selectedIds.value.join(','),itemId:Number(route.query.itemId)||undefined,...(production.value?{view:'production'}:{})}
 try{const r=presentation.value==='matrix'?await api.getMoldSalesMatrix(params):await api.getMoldSales(params);if(ticket!==epoch||auth!==user.token)return;if(presentation.value==='matrix')matrix.value=r as api.MoldSalesMatrixPage;else data.value=r as api.SalesPage;job.value=r.status.job;if(job.value?.status==='running')schedulePoll()}catch(e){if(ticket===epoch&&auth===user.token)error.value=e instanceof Error?e.message:'读取失败，请重试'}finally{if(ticket===epoch)loading.value=false}
}
async function refresh(){const ticket=++optionsEpoch,auth=user.token;ready.value=false;loading.value=true;try{const value=await api.getMoldSalesOptions();if(ticket!==optionsEpoch||auth!==user.token)return;metadata.value=value;if(preferences.savedProductLineIds.value===undefined)preferences.chooseProducts(defaultIds.value);if(brandId.value&&!value.brands.some(b=>b.brandId===Number(brandId.value)))brandId.value=undefined;readyAuth=auth;readyOwner=user.profile?.userId;ready.value=true;await load()}catch(e){if(ticket===optionsEpoch&&auth===user.token){error.value=e instanceof Error?e.message:'产品与品牌读取失败，请重试';loading.value=false}}}
function reset(){page.value=1;void load()}
watch(keyword,()=>{clearTimeout(timer);timer=setTimeout(reset,300)})
watch(()=>workspace.revision,()=>{void refresh();if(detailOpen.value&&detail.value)void loadDetail()});
watch([filter,brandId,size,presentation,()=>selectedIds.value.join(',')],reset,{flush:'sync'});watch(()=>route.query.itemId,reset)
function openGroup(id:number,tab='orders'){detail.value=undefined;detailOpen.value=true;detailPage.value=1;detailTab.value=tab;return loadDetail(id)}
function openMatrix(cell:api.MoldSalesMatrixCell,row:api.MoldSalesMatrixRow){
 if(cell.groupIds.length===1&&!cell.applicationIds.length){void openGroup(cell.groupIds[0]!);return}
 if(!cell.groupIds.length&&cell.applicationIds.length===1){void router.push({path:'/mold-applications',query:{applicationId:String(cell.applicationIds[0])}});return}
 if(!cell.groupIds.length&&!cell.applicationIds.length&&cell.itemIds?.length){
  if(cell.itemIds.length===1){moldItem(cell.itemIds[0]!);return}
  choiceRows.value=cell.itemIds.map(itemId=>({itemId,productName:options.value.find(p=>p.productLineId===cell.productLineId)?.productName||'产品',modelNames:row.modelNames,phoneCodes:row.phoneCodes}));choiceOpen.value=true;return
 }
 const productName=options.value.find(p=>p.productLineId===cell.productLineId)?.productName||'产品'
 choiceRows.value=[...cell.groupIds.map(groupId=>{const group=cell.groups?.find(g=>g.groupId===groupId);return {groupId,productName,modelNames:group?.modelNames||row.modelNames,phoneCodes:group?.phoneCodes||row.phoneCodes,salesQuantity:group?.salesQuantity}}),...cell.applicationIds.map(applicationId=>({applicationId,productName,modelNames:row.modelNames,phoneCodes:row.phoneCodes}))];choiceOpen.value=true
}
function openMatrixTotal(row:api.MoldSalesMatrixRow){const cells=row.cells.filter(c=>c.groupIds.length);if(cells.length===1){openMatrix(cells[0]!,row);return}choiceRows.value=cells.flatMap(cell=>cell.groupIds.map(groupId=>{const group=cell.groups?.find(g=>g.groupId===groupId);return {groupId,productName:options.value.find(p=>p.productLineId===cell.productLineId)?.productName||'产品',modelNames:group?.modelNames||row.modelNames,phoneCodes:group?.phoneCodes||row.phoneCodes,salesQuantity:group?.salesQuantity}}));choiceOpen.value=true}
function chooseEvidence(value:typeof choiceRows.value[number]){choiceOpen.value=false;if(value.groupId)void openGroup(value.groupId);else if(value.applicationId)void router.push({path:'/mold-applications',query:{applicationId:String(value.applicationId)}});else if(value.itemId)moldItem(value.itemId)}
async function pollJob(){const auth=user.token;try{const r=await api.getMoldSalesJob();if(disposed||auth!==user.token)return;job.value=r;if(r.status==='running')schedulePoll();else if(r.status==='completed'){workspace.changed();ElMessage.success(r.kind==='archive'?'历史订单已导入':r.kind==='historyReview'?'历史分类和型号对照已保存':'CRM 订单已更新')}else if(r.status==='failed')error.value=r.message||'更新失败，原数据保留'}catch(e){if(auth===user.token)error.value=e instanceof Error?e.message:'读取更新进度失败，请刷新'}}
function schedulePoll(){clearTimeout(poll);poll=setTimeout(()=>void pollJob(),2500)}
async function sync(){const auth=user.token;try{await ElMessageBox.confirm('只读更新 CRM 销售订单，取消订单将从有效销量中排除。原有生产数量和模具资料保留。','更新 CRM 订单',{confirmButtonText:'开始更新',cancelButtonText:'取消'});if(auth!==user.token)return;job.value=await api.syncMoldSales();schedulePoll()}catch(e){if(auth===user.token&&e!=='cancel'&&e!=='close')error.value=e instanceof Error?e.message:'更新未开始'}}
async function open(row:api.MoldSalesGroup,tab='orders'){await openGroup(row.groupId,tab)}
async function loadDetail(id=detail.value?.group.groupId){if(!id)return;const ticket=++detailEpoch,auth=user.token;detailLoading.value=true;try{const next=await (production.value?api.getMoldSalesDetail(id,detailPage.value,'production'):api.getMoldSalesDetail(id,detailPage.value));if(ticket===detailEpoch&&auth===user.token)detail.value=next}catch(e){if(ticket===detailEpoch&&auth===user.token)error.value=e instanceof Error?e.message:'明细读取失败'}finally{if(ticket===detailEpoch)detailLoading.value=false}}
async function openHistory(){const auth=user.token;try{const next=await api.getMoldSalesHistory();if(auth===user.token){history.value=next;historyOpen.value=true}}catch(e){error.value=e instanceof Error?e.message:'读取历史失败'}}
function openUnmatched(){unmatchedOpen.value=true}
async function loadArchiveSources(){
 const ticket=++archiveEpoch,auth=user.token;archiveLoading.value=true;archiveError.value=''
 try{const sources=await api.getSalesArchiveSources();if(disposed||ticket!==archiveEpoch||auth!==user.token||!archiveOpen.value)return;archiveSources.value=sources;if(!sources.some(source=>source.sha256===archiveHash.value))archiveHash.value=(sources.find(source=>source.prepared&&!source.imported)||sources[0])?.sha256||''}
 catch(e){if(ticket===archiveEpoch&&auth===user.token)archiveError.value=e instanceof Error?e.message:'历史资料读取失败，请重试'}
 finally{if(ticket===archiveEpoch)archiveLoading.value=false}
}
function openArchiveImport(){if(isRunning.value)return;archiveOpen.value=true;archiveUnknown.value=false;archiveSources.value=[];archiveHash.value='';void loadArchiveSources()}
async function checkArchiveState(){
 const auth=user.token;await Promise.all([loadArchiveSources(),refresh()]);if(disposed||auth!==user.token)return
 if(archiveSource.value?.imported||job.value?.status==='running'||job.value?.status==='failed')archiveUnknown.value=false
}
async function importArchive(){
 const source=archiveSource.value;if(!source||!source.prepared||source.imported||archiveLoading.value||archiveSaving.value||archiveUnknown.value||isRunning.value)return
 const auth=user.token,ticket=++archiveEpoch;archiveSaving.value=true;archiveError.value=''
 try{const result=await api.importSalesArchive({file:source.file,sha256:source.sha256});if(disposed||ticket!==archiveEpoch||auth!==user.token)return;job.value=result;archiveOpen.value=false;if(result.status==='running')schedulePoll();else if(result.status==='completed'){workspace.changed();ElMessage.success('历史订单已导入')}else if(result.status==='failed')error.value=result.message||'历史订单未导入，原资料保留'}
 catch(e){if(ticket===archiveEpoch&&auth===user.token){archiveUnknown.value=true;archiveError.value=`${e instanceof Error?e.message:'导入请求未确认'}。请刷新状态核对，暂不重复提交。`}}
 finally{if(ticket===archiveEpoch)archiveSaving.value=false}
}
function maintain(id?:number){detailOpen.value=false;emit('maintain',id)}
function moldItem(itemId:number){void router.push({path:'/molds',query:{itemId}})}
function mold(row:api.MoldSalesGroup){moldItem(row.groupId)}
watch(()=>user.token,()=>{++epoch;++detailEpoch;++optionsEpoch;++archiveEpoch;clearTimeout(poll);clearTimeout(timer);ready.value=false;data.value=undefined;matrix.value=undefined;metadata.value={products:[],brands:[]};detail.value=undefined;detailOpen.value=false;history.value=[];historyOpen.value=false;unmatchedOpen.value=false;choiceRows.value=[];choiceOpen.value=false;productsOpen.value=false;brandId.value=undefined;job.value=undefined;error.value='';loading.value=false;detailLoading.value=false;costOpen.value=false;costGroupId.value=undefined;archiveOpen.value=false;archiveSources.value=[];archiveHash.value='';archiveError.value='';archiveUnknown.value=false;archiveLoading.value=false;archiveSaving.value=false})
watch(()=>user.profile?.userId,(next,previous)=>{if(next&&next!==previous&&user.token)void refresh()})
onMounted(()=>void refresh())
defineExpose({refresh})
onBeforeUnmount(()=>{disposed=true;++epoch;++detailEpoch;++optionsEpoch;++archiveEpoch;clearTimeout(timer);clearTimeout(poll)})
</script>
<template>
 <section class="mold-sales">
  <header class="sales-titlebar"><h2>{{production?'累计产量':'模具销量与成本'}}</h2><div v-if="!production" class="view-switch" role="tablist" aria-label="销量展示视图"><button :class="{selected:presentation==='detail'}" role="tab" :aria-selected="presentation==='detail'" @click="chooseView('detail')">产品明细</button><button :class="{selected:presentation==='matrix'}" role="tab" :aria-selected="presentation==='matrix'" @click="chooseView('matrix')">型号总览</button></div><div class="tools"><slot name="tools"/><span class="source-date">CRM 更新：{{date(status?.capturedAt)}}</span><el-button size="small" @click="refresh">刷新统计</el-button><el-button v-if="!production&&(status?.canImportArchive??status?.canSync)" size="small" :disabled="isRunning" @click="openArchiveImport">导入历史订单</el-button><el-button v-if="status?.canSync" size="small" type="primary" :loading="isRunning" @click="sync">更新 CRM 订单</el-button><el-button v-if="!production&&status?.canSync&&status.canReadCost" size="small" text @click="openHistory">取数与成本历史</el-button><el-popover placement="bottom-end" :width="340" trigger="click"><template #reference><el-button size="small" text aria-label="销量及资料说明">资料说明</el-button></template><p class="notice">销量及订单累计依据不代表模具实物或手机适配已经确认。</p><p class="notice">历史型号、适配等资料缺项不在每个单元格重复显示。点击数量或模具资料可查看原始依据，也可按“型号关联待核对”单独筛选。</p><p v-if="current?.ignoredQuantity" class="notice">另有 {{qty(current.ignoredQuantity)}} 件历史订单在下单系统未找到对应款式／机型，本次暂不处理，原订单保留。</p></el-popover></div></header>
  <div class="filters">
   <el-input v-model="keyword" :aria-label="production?'搜索累计产量':'搜索模具销量'" size="small" clearable placeholder="搜索品牌、产品、手机型号或编码"/>
   <el-select v-model="brandId" aria-label="品牌筛选" size="small" clearable placeholder="全部品牌"><el-option v-for="b in brands" :key="b.brandId" :value="b.brandId" :label="b.brandName"/></el-select>
   <el-popover v-model:visible="productsOpen" placement="bottom-start" :width="330" trigger="click" @show="refresh"><template #reference><el-button class="product-picker" size="small">{{presentation==='matrix'?'产品列':'产品筛选'}} · 已选 {{selectedIds.length}} <span aria-hidden="true">⌄</span></el-button></template><div class="product-choices"><strong>自有产品</strong><el-input v-model="productSearch" size="small" clearable placeholder="搜索产品名称或编码" aria-label="搜索产品列"/><div class="choice-tools"><el-button size="small" link type="primary" @click="chooseProducts(defaultIds)">常用</el-button><el-button size="small" link type="primary" @click="chooseProducts(options.map(p=>p.productLineId))">全选</el-button><el-button size="small" link @click="chooseProducts([])">清空</el-button></div><div class="product-options"><label v-for="p in filteredProducts" :key="p.productLineId"><input type="checkbox" :checked="selectedIds.includes(p.productLineId)" @change="toggleProduct(p.productLineId,($event.target as HTMLInputElement).checked)"/><span>{{p.productName}}<small v-if="p.productCode||p.styleCode">{{p.productCode||p.styleCode}}</small></span><small v-if="p.status==='draft'||p.masterDataStatus==='draft'" class="draft-label">草稿</small></label><p v-if="!filteredProducts.length" class="notice">暂无符合条件的自有产品</p></div><p class="notice">新增产品会进入此清单，已保存的选择保持不变。</p><p v-if="!preferences.storageAvailable.value" class="notice">浏览器未能保存偏好，本次选择仍有效。</p></div></el-popover>
   <el-select v-model="filter" :aria-label="production?'产量筛选':'销量筛选'" size="small"><el-option value="all" label="全部模具组"/><template v-if="production"><el-option value="withProduction" label="有产量依据"/><el-option value="missingProduction" label="待核对产量"/></template><template v-else><el-option value="withSales" label="有销量"/><el-option value="missingCost" label="成本待补"/></template><el-option value="unmapped" label="型号关联待核对"/></el-select>
   <span class="totals">当前筛选 {{qty(current?.totalElements)}} {{presentation==='matrix'?'款型号':'组'}} · {{production?'有效订单':'已选产品销量'}} {{qty(production?current?.totalOrderQuantity:current?.totalSalesQuantity)}} 件</span>
  </div>
  <p class="source-scope">2025年前：数据来自 eccount；2025年起：数据来自 crm。三家公司按订单量合计。<span v-if="status?.archive&&!status.archive.imported">历史订单尚未导入。</span></p>
  <el-alert v-if="error" :title="error" type="error" :closable="false"><el-button text @click="refresh">重试</el-button></el-alert>
  <p v-if="isRunning" class="notice" role="status">{{job?.message||'正在只读更新 CRM 订单，完成前仍显示上次成功数据。'}}</p>
  <div v-if="status?.canReadHistoryReview" class="reconciliation-notices"><p class="notice"><el-button link type="primary" @click="openUnmatched">{{status.historyReview?.applied?"查看历史订单处理结果":"历史订单处理"}}</el-button><span v-if="status.historyReview?.applied"> · 按原编码整理 {{qty(Number(status.historyReview.summary?.categories.coded_history.quantity||0))}} 件 · 外购 {{qty(Number(status.historyReview.summary?.categories.purchased.quantity||0))}} 件 · 待补 {{qty(Number(status.historyReview.summary?.categories.pending.quantity||0))}} 件</span><span v-else-if="current?.unassignedQuantity"> · {{qty(current.unassignedQuantity)}} 件待核对，原单原码保留</span></p></div>
  <MoldSalesMatrix v-if="presentation==='matrix'" :data="matrix" :products="selectedProducts" v-loading="loading" @open="openMatrix" @total="openMatrixTotal"/>
  <div v-else class="sales-list" role="table" :aria-label="production?'模具累计产量列表':'模具销量与成本列表'" v-loading="loading">
   <div class="sales-row column-head" :class="{'without-cost':production||!status?.canReadCost}" role="row"><span>品牌</span><span>产品</span><span>手机型号 / 编码</span><span>{{production?'累计产量':'有效订单件数'}}</span><template v-if="!production&&status?.canReadCost"><span>模具成本</span><span>每件分摊</span><span>参考回本销量</span></template><span>操作</span></div>
   <div class="sales-body">
    <article v-for="r in data?.content" :key="r.groupId" class="sales-row" :class="{'without-cost':production||!status?.canReadCost}" role="row">
     <div class="brand-identity" role="cell"><small class="narrow-label">品牌</small>{{brandNames(r)}}</div>
     <div class="product-identity" role="cell"><small class="narrow-label">产品</small><strong>{{r.productName||r.styleName}}</strong></div>
     <div class="identity" role="cell"><small class="narrow-label">手机型号</small><button @click="open(r)"><span>{{r.modelNames.join(' / ')||'未登记型号'}}</span></button><small v-if="r.phoneCodes.length">编码 {{r.phoneCodes.join(' / ')}}</small><small v-if="r.coverageLabel&&!['historical','needs_review'].includes(r.coverageState||'')" class="coverage-label">{{r.coverageLabel}}</small></div>
     <div role="cell" class="metric"><small class="narrow-label">{{production?'累计产量':'有效订单'}}</small><button class="quantity-link" @click="open(r)">{{qty(production?r.production?.finishedTotal:r.salesQuantity)}}<small>件</small></button><small v-if="r.sourceBreakdown" class="source-breakdown">{{sourceBreakdown(r.sourceBreakdown)}}</small><small v-if="production&&componentDifference(r)" class="component-difference">部件差异：{{componentDifference(r)}}</small></div>
     <template v-if="!production&&status?.canReadCost"><div role="cell" class="metric"><small class="narrow-label">模具成本</small><strong v-if="r.costConflict">成本归属待核对</strong><template v-else><strong>{{r.cost?'¥'+money(r.cost.totalCost):'成本待补'}}</strong><small v-if="r.cost">{{costLabel(r.cost)}}<template v-if="r.cost.source!=='actual'"> · {{r.cost.costSets}} 套</template></small></template></div><div role="cell" class="metric"><small class="narrow-label">每件分摊</small><strong>{{!r.costConflict&&r.cost?.perUnitCost!=null?'¥'+money(r.cost.perUnitCost):'—'}}</strong><small v-if="r.salesQuantity===0">暂无有效销量</small></div><div role="cell" class="metric"><small class="narrow-label">参考回本销量</small><span>{{!r.costConflict&&r.cost?.breakEvenUnits!=null?qty(r.cost.breakEvenUnits)+' 件':'—'}}</span><small v-if="!r.costConflict&&r.cost?.remainingUnits!=null">{{r.cost.remainingUnits>0?'还差 '+qty(r.cost.remainingUnits)+' 件':'已达到参考销量'}}</small></div></template>
     <div role="cell" class="row-tools"><el-button size="small" link type="primary" @click="open(r)">{{production?'产量依据':'查看明细'}}</el-button><el-button v-if="production" size="small" link @click="maintain(r.groupId)">补录／更正</el-button><template v-else><el-button v-if="canMaintainRowCost(r)" size="small" link type="primary" @click="editCost(r)">维护成本</el-button><el-button size="small" link @click="mold(r)">模具资料</el-button></template></div>
    </article>
    <el-empty v-if="data&&!data.content.length" :description="status?.connected?'当前条件下暂无模具':'尚未拉取 CRM 订单，点击上方更新后查看'"/>
   </div>
  </div>
  <footer><small>{{status?.periodStart||'2025-01-01'}} 至 {{status?.periodEnd||'今天'}}，{{production?'列表显示成品累计，部件差异另示。以已计入的订单件数为累计依据，交付与否不影响计入；与已有人工累计分别取较大值，共模归并、不重复相加。':'按已计入的手机壳订单量分摊；待核对原行另存，不当作确定销量。实际成本优先，否则仅作预算参考；共模机型合并，整套成本不重复计算。'}}</small><el-pagination v-model:current-page="page" v-model:page-size="size" :total="current?.totalElements||0" :pager-count="5" size="small" layout="prev,pager,next" @current-change="load"/></footer>
  <el-drawer v-model="choiceOpen" title="选择查看依据" size="min(620px,96vw)"><p class="notice">同一型号下有多份档案，分别查看原订单及成本。</p><button v-for="value in choiceRows" :key="value.groupId?`g${value.groupId}`:value.applicationId?`a${value.applicationId}`:`m${value.itemId}`" class="evidence-choice" @click="chooseEvidence(value)"><strong>{{value.productName}}</strong><span>{{value.modelNames.join(' / ')}}</span><small>编码 {{value.phoneCodes.join(' / ')||'待核对'}} · {{value.groupId?'档案 '+value.groupId:value.applicationId?'申请 '+value.applicationId:'模具档案 '+value.itemId}}<template v-if="value.salesQuantity!=null"> · {{qty(value.salesQuantity)}} 件</template></small></button></el-drawer>
  <el-drawer v-model="detailOpen" class="sales-detail" :title="production?'累计产量与订单依据':'模具销量与成本明细'" size="min(1080px,96vw)" :destroy-on-close="true">
   <div v-loading="detailLoading" class="detail-content"><template v-if="detail">
    <h3>{{detail.group.styleName}} · {{detail.group.modelNames.join(' / ')}}</h3>
    <div class="detail-summary"><span v-if="production">有效订单 {{qty(detail.group.production?.orderQuantity)}} 件 · PC {{qty(detail.group.production?.pcTotal)}} · TPU {{qty(detail.group.production?.tpuTotal)}} · 成品 {{qty(detail.group.production?.finishedTotal)}}</span><span v-else>有效销量 {{qty(detail.group.salesQuantity)}} 件</span><span v-if="!production&&status?.canReadCost&&detail.group.cost&&!detail.group.costConflict">{{costLabel(detail.group.cost)}} ¥{{money(detail.group.cost.totalCost)}} · 每件分摊 ¥{{money(detail.group.cost.perUnitCost)}}</span><el-button v-if="!production&&canMaintainRowCost(detail.group)" size="small" @click="editCost(detail.group)">维护成本</el-button><el-button size="small" @click="mold(detail.group)">核对模具与共模机型</el-button></div>
    <p v-if="detail.group.sourceBreakdown" class="notice detail-sources">{{sourceBreakdown(detail.group.sourceBreakdown)}}；三家公司按订单量合计，不代表集团对外唯一实销。</p>
    <p class="notice">手机型号编码：{{detail.group.phoneCodes.join(' / ')||'待核对'}}</p>
    <p v-if="detail.group.coverageLabel||detail.group.unmapped" class="notice coverage-evidence"><span v-if="detail.group.coverageLabel">{{detail.group.coverageLabel}}</span><span v-if="detail.group.unmapped"> · 型号关联资料未齐，请在模具资料中补充真实适用手机。</span></p>
    <p v-for="a in detail.group.salesAliases" :key="a.phoneCode" class="notice alias-evidence">历史编码 {{a.phoneCode}} 已关联本档案：{{a.reason}}。订单原名称及编码保留。</p>
    <el-tabs v-model="detailTab"><el-tab-pane :label="production?'订单依据':'订单明细'" name="orders"/><el-tab-pane v-if="production||status?.canReadCost" :label="production?'产量依据':'成本依据'" name="cost"/></el-tabs>
    <template v-if="detailTab==='orders'">
     <p class="notice">{{production?'已登记且可核实的订单计入，不以发货、到货或完成状态为门槛。同一共模组的机型和颜色合计一次；取消、删除和待核对明细不计入。':'每行保留原订单。2025年前取 eccount，2025年起取 crm；同期 Excel 仅核对，不重复叠加。多个颜色合计到同一模具组；多个实物套的销量不做无依据拆分。'}}</p>
     <div class="phone-breakdown"><span v-for="p in detail.phoneSales" :key="p.phoneCode">{{p.modelName}}（{{p.targetPhoneCode||p.phoneCode}}）：{{qty(p.quantity)}} 件<small v-if="p.historicalAlias">原编码 {{p.phoneCode}} · 原名 {{p.originalModelName||'未填写'}}<template v-if="p.associationReason"> · {{p.associationReason}}</template></small></span></div>
     <div class="order-list"><article v-for="o in detail.orders" :key="o.sourceId" class="order-row"><div><strong>{{o.orderNo||'原单未填外部单号'}}</strong><small>{{o.date||(o.orderDate?date(new Date(Number(o.orderDate)).toISOString()):'原订单未填日期')}}</small><small>{{orderStates[o.orderStatus]||o.orderStatus||'原单未填状态'}}</small><small class="order-source">{{sourceLabel(o)}}<template v-if="o.company"> · {{o.company}}</template></small></div><div>{{o.name}}<small>{{o.specification}}</small><small>{{o.itemCode}}</small><small v-if="o.sourceFile" class="order-location">原件：{{o.sourceFile}}<template v-if="o.sourceSheet"> · {{o.sourceSheet}}</template><template v-if="o.sourceRow!=null"> · 第 {{o.sourceRow}} 行</template></small></div><div><strong>{{orderQuantity(o)}}</strong><small :class="{'excluded':o.eligibility!=='eligible'}">{{production&&o.eligibility==='eligible'?'计入累计依据':eligibility[o.eligibility]||'原单待核对'}}</small></div></article></div>
     <el-pagination v-model:current-page="detailPage" :page-size="20" :total="detail.totalElements" :pager-count="5" size="small" layout="total,prev,pager,next" @current-change="loadDetail()"/>
    </template>
    <template v-else-if="detailTab==='cost'">
     <template v-if="production">
      <p class="notice">按 {{status?.periodStart}} 至 {{status?.periodEnd}} 的已计入订单件数作为累计依据，不按交付进度筛选。人工原值保留，每一项累计分别取已有记录与订单数量的较大值；同一共模组多条旧档案的累计也取较大值。</p>
      <p v-if="detail.group.delivery" class="notice">未交付订单 {{qty(detail.group.delivery.pendingQuantity)}} 件；部分交付订单涉及 {{qty(detail.group.delivery.partialOrderQuantity)}} 件。两项均已包含在订单累计依据内；部分交付不推算未交件数。</p>
      <dl class="production-breakdown"><dt>项目</dt><dt>已有人工累计</dt><dt>销售订单依据</dt><dt>本页累计</dt><template v-for="[key,manual,label] in [['pcTotal','manualPcTotal','PC 半成品'],['tpuTotal','manualTpuTotal','TPU 半成品'],['finishedTotal','manualFinishedTotal','成品']] as const" :key="key"><dt>{{label}}</dt><dd>{{qty(detail.group.production?.[manual])}}</dd><dd>{{qty(detail.group.production?.orderQuantity)}}</dd><dd>{{qty(detail.group.production?.[key])}}</dd></template></dl>
      <p class="notice">原始补录记录与更正历史</p><article v-for="record in detail.group.productionRecords" :key="record.itemId" class="history-record"><strong>{{record.modelName}} · 档案 {{record.itemId}}</strong><p>PC {{qty(record.pcTotal)}} · TPU {{qty(record.tpuTotal)}} · 成品 {{qty(record.finishedTotal)}}</p><p v-if="record.productionNotes">{{record.productionNotes}}</p><el-button size="small" @click="maintain(record.itemId)">补录／更正本档案</el-button></article>
      <p class="notice">CRM 更新：{{date(status?.capturedAt)}}。原订单和历次取数依据保留；上面的累计结果根据当前依据计算，不覆盖人工填写值。</p>
     </template>
     <template v-else-if="status?.canReadCost">
      <el-alert v-if="detail.group.costConflict" title="成本归属待核对，请先核对模具与共模机型，历史成本不自动合并。" type="warning" :closable="false"/>
      <template v-else-if="detail.group.cost">
       <dl v-if="detail.group.cost.source==='actual'&&detail.group.cost.actual" class="cost-breakdown actual-cost-breakdown"><dt>制模费</dt><dd>¥{{money(detail.group.cost.actual.manufacturingCost)}}</dd><dt>运费</dt><dd>¥{{money(detail.group.cost.actual.freightCost)}}</dd><dt>清关费</dt><dd>¥{{money(detail.group.cost.actual.customsCost)}}</dd><dt>其他费用</dt><dd>¥{{money(detail.group.cost.actual.otherCost)}}</dd><dt>本组实际成本</dt><dd>¥{{money(detail.group.cost.totalCost)}}</dd><dt>最近维护</dt><dd>{{detail.group.cost.actual.updatedBy}} · {{date(detail.group.cost.actual.updatedAt)}}</dd></dl>
       <p v-else class="notice">尚未维护实际成本，当前金额仅为预算参考。</p>
       <p class="cost-apportionment">本组分摊：¥{{money(detail.group.cost.totalCost)}} ÷ {{qty(detail.group.salesQuantity)}} 件 = {{detail.group.cost.perUnitCost==null?'暂无销量，暂不计算':'¥'+money(detail.group.cost.perUnitCost)+'/件'}}</p>
       <section class="break-even-evidence"><h4>参考回本销量</h4><template v-if="detail.group.cost.breakEvenUnits!=null"><p class="break-even-result"><strong>{{qty(detail.group.cost.breakEvenUnits)}} 件</strong><span v-if="detail.group.cost.remainingUnits!=null">{{detail.group.cost.remainingUnits>0?'还差 '+qty(detail.group.cost.remainingUnits)+' 件':'已达到参考销量'}}</span></p><p v-if="detail.group.cost.basis" class="notice">本组{{detail.group.cost.source==='actual'?'实际成本':'预算'}} ¥{{money(detail.group.cost.totalCost)}} ÷（参考售价 ¥{{detail.group.cost.basis.referenceSellingPrice}} − 单件生产成本 ¥{{detail.group.cost.basis.referenceUnitProductionCost}}），向上取整。</p><p class="notice">按订单量估算，不代表已收到货款或收回实际投入。</p></template><p v-else class="notice">{{breakEvenIssue(detail.group.cost)}}</p></section>
       <el-button size="small" @click="editCost(detail.group)">查看成本记录</el-button>
       <details v-if="detail.group.cost.basis" class="budget-evidence"><summary>查看原预算依据</summary><dl class="cost-breakdown"><dt>原表款式</dt><dd>{{detail.group.cost.basis.sourceStyleName}}</dd><dt>制模成本／套</dt><dd>¥{{money(Number(detail.group.cost.basis.moldManufacturing))}}</dd><dt>运输／套</dt><dd>{{detail.group.cost.basis.weightKg}} kg × ¥{{detail.group.cost.basis.freightPerKg}} = ¥{{money(Number(detail.group.cost.basis.freight))}}</dd><dt>清关／套</dt><dd>¥{{money(Number(detail.group.cost.basis.customs))}}</dd><dt>燃油附加／套</dt><dd>{{detail.group.cost.basis.weightKg}} kg × ¥{{detail.group.cost.basis.fuelPerKg}} = ¥{{money(Number(detail.group.cost.basis.fuel))}}</dd><dt>预算合计／套</dt><dd>¥{{money(Number(detail.group.cost.basis.landedTotal))}}</dd><dt>本组预算参考</dt><dd>¥{{money(detail.group.cost.budgetTotalCost??(detail.group.cost.source==='actual'?null:detail.group.cost.totalCost))}}</dd></dl><p class="notice">来源：模具成本预算.xlsx，{{detail.group.cost.basis.sourceSheet}} 第 {{detail.group.cost.basis.sourceRow}} 行。预算沿用原公式费率。参考回本不能据此认定已收到货款或收回实际投入。</p></details>
      </template>
      <el-empty v-else description="尚未维护实际成本，原表也未提供预算"/>
     </template>
    </template>
   </template></div>
  </el-drawer>
  <MoldCostEditor v-if="status?.canReadCost&&costOpen" v-model="costOpen" :group-id="costGroupId" :can-write="canMaintainCost&&costWritable" @saved="costSaved"/>
  <el-drawer v-model="historyOpen" title="取数与成本历史" size="min(850px,96vw)"><section v-if="status?.archive?.imported" class="history-record"><h3>历史订单来源</h3><p>数据来自 eccount · {{status.archive.companies?.join(' / ')||'三家公司'}}</p><p>明细 {{qty(status.archive.detailRows)}} 行 · 2025年前 {{qty(status.archive.pre2025Rows)}} 行 · 待核对 {{qty(status.archive.reviewRows)}} 行</p><small>导入时间：{{date(status.archive.importedAt)}}。待核对原行保留，未当作确定销量。</small></section><article v-for="h in history" :key="h.id" class="history-record"><strong>{{date(h.capturedAt)}}</strong><small>来源校验 {{h.sourceHash.slice(0,16)}}</small><p v-for="b in h.costs.rows" :key="b.sourceStyleName">{{b.sourceStyleName}} · 每套 ¥{{money(Number(b.landedTotal))}}</p></article></el-drawer>
  <el-dialog v-model="archiveOpen" title="导入历史销售订单" width="min(660px,96vw)" top="24px" :close-on-click-modal="false" :close-on-press-escape="!archiveSaving" :show-close="!archiveSaving">
   <div v-loading="archiveLoading" class="archive-import-content"><el-alert v-if="archiveError" :title="archiveError" type="error" :closable="false"/><template v-if="archiveSources.length"><div v-if="archiveSources.length>1" class="archive-source-options"><label v-for="(source,index) in archiveSources" :key="source.sha256"><input v-model="archiveHash" type="radio" :value="source.sha256" :disabled="archiveSaving||archiveUnknown"/>历史订单资料 {{index+1}}<span v-if="source.imported">（已导入）</span></label></div><section v-if="archiveSource" class="archive-import-summary"><h3>已核对的 eccount 销售订单</h3><dl><dt>原文件</dt><dd>{{qty(archiveSource.sourceFileCount)}} 份 Excel</dd><dt>所属公司</dt><dd>{{archiveSource.companies.join(' / ')}}</dd><dt>订单明细</dt><dd>{{qty(archiveSource.detailRows)}} 行</dd><dt>2025年前明细</dt><dd>{{qty(archiveSource.pre2025DetailRows)}} 行</dd></dl><p>2025年前显示“数据来自 eccount”，与2025年起的 crm 订单合并统计。三家公司按订单量相加，保留所属公司。</p><p>2025年起的 Excel 只用于核对，不重复计入。数量、单位或状态待核对的原行仍保留。</p><p v-if="archiveSource.imported" class="archive-import-state">这份历史资料已导入，不会重复累加。</p><p v-else-if="!archiveSource.prepared" class="archive-import-state">{{archiveSource.message||'历史资料尚未准备完成，请稍后刷新。'}}</p></section></template><p v-else-if="!archiveLoading&&!archiveError" class="notice">尚无已准备的历史订单资料。此入口只导入已核对的服务器资料，不支持直接上传任意 Excel。</p></div>
   <template #footer><el-button :disabled="archiveSaving" @click="archiveOpen=false">关闭</el-button><el-button :disabled="archiveSaving||archiveLoading" @click="checkArchiveState">刷新状态</el-button><el-button v-if="archiveSource&&!archiveSource.imported" type="primary" :loading="archiveSaving" :disabled="archiveLoading||!archiveSource.prepared||archiveUnknown||isRunning" @click="importArchive">确认导入历史订单</el-button></template>
  </el-dialog>
  <MoldSalesHistoryReview v-model="unmatchedOpen" @changed="workspace.changed()"/>
 </section>
</template>
